WITH latest_snapshots AS (SELECT * FROM scores.stage_snapshots WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM scores.stage_snapshots)),
portfolio_analysis AS (SELECT h.symbol, h.qty, s.stage, s.trading_signal, s.relative_strength, s.stage_score FROM portfolio.holdings h JOIN latest_snapshots s ON h.symbol = s.symbol) 
SELECT symbol, qty, stage, trading_signal, relative_strength, stage_score FROM portfolio_analysis WHERE trading_signal IN ('BUY', 'STRONG_BUY') LIMIT 10;
